const seen = new Set();
const out = [];

function tryParseRSS(text, srcName) {
  const items = [];
  const t = text || "";
  const entryRegex = /<item[\s\S]*?<\/item>/g;
  const atomEntryRegex = /<entry[\s\S]*?<\/entry>/g;
  const blocks = t.match(entryRegex) || t.match(atomEntryRegex) || [];
  for (const b of blocks) {
    const get = (re) => ((b.match(re) || [])[1] || "").replace(/<!\[CDATA\[|\]\]>/g, "").trim();
    const title = get(/<title[^>]*>([\s\S]*?)<\/title>/);
    const link  = get(/<link[^>]*>([\s\S]*?)<\/link>/) || get(/<link[^>]*href=["']([\s\S]*?)["'][^>]*\/>/);
    const pub   = get(/<(pubDate|updated|published)[^>]*>([\s\S]*?)<\/\1>/) || new Date().toISOString();
    const desc  = get(/<(description|summary|content)[^>]*>([\s\S]*?)<\/\1>/);
    if (title && link) items.push({ title, link, publishedAt: pub, summary: desc, source: srcName || "rss" });
  }
  return items;
}

for (const it of items) {
  const payload = it.json; // จาก HTTP เป็น string (RSS)
  const rows = typeof payload === "string" ? tryParseRSS(payload, "web") : [];
  for (const r of rows) {
    const title = (r.title || "").trim();
    const url   = (r.link  || "").trim();
    if (!title || !url) continue;
    const key = (title + "|" + url).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      source: r.source || "web",
      url, title,
      body: (r.summary || "").trim(),
      publishedAt: r.publishedAt || r.pubDate || new Date().toISOString()
    }});
  }
}
return out;
// ทดสอบครั้งแรกข่าวเยอะไป? เติม:  return out.slice(0, 20);

// รวมทุกไอเท็มที่เข้ามาให้เป็น 1 ก้อน เพื่อส่งต่อ
const all = $input.all();
if (!all || all.length === 0) {
  return [{ json: { items: [] } }];
}
const news = all.map(i => i.json);
return [{ json: { items: news } }];

