// รับ input จาก Join AI Input
const data = items[0].json;

// แยกออกมา
const news = data.items || [];
const watchlist = data.watchlist || [];

// รวมเป็นโครงเดียว
return [{
  json: {
    news,
    watchlist
  }
}];

/**
 * Build Email HTML from AI Agent JSON
 * EXPECTED INPUT (from AI Agent):
 * {
 *   run_title: "Investor Daily Brief",
 *   as_of: "2025-09-20 16:00 ICT",
 *   items: [
 *     {
 *       title, url, source, publishedAt,
 *       summary, sentiment, 
 *       impact: { on_portfolio, rationale },
 *       tickers: [...]
 *     }
 *   ]
 * }
 */

const data = $json || {};

function esc(s){
  return String(s ?? '').replace(/[&<>"]/g, m => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'
  }[m]));
}

const title = esc(data.run_title || 'Investor Daily Brief');
const asOf  = esc(data.as_of || new Date().toISOString());
const items = Array.isArray(data.items) ? data.items : [];

const header = `
<div style="font-family:ui-sans-serif,system-ui,Segoe UI,Arial;max-width:800px;margin:auto;padding:16px">
  <h2 style="margin:0 0 6px">${title}</h2>
  <div style="color:#64748b;font-size:13px;margin-bottom:12px">as of ${asOf}</div>
`;

const rows = items.map((it, i) => {
  const t   = esc(it.title);
  const url = esc(it.url);
  const src = esc(it.source);
  const pub = esc(it.publishedAt);
  const sum = esc(it.summary);
  const sen = esc(it.sentiment);
  const imp = esc(it.impact?.on_portfolio || '');
  const rat = esc(it.impact?.rationale || '');
  const ticks = Array.isArray(it.tickers) ? esc(it.tickers.join(', ')) : '';

  const senColor = sen === 'Positive' ? '#16a34a'
                   : sen === 'Negative' ? '#dc2626'
                   : '#6b7280';
  const impColor = imp === 'Bullish' ? '#16a34a'
                   : imp === 'Bearish' ? '#dc2626'
                   : imp === 'Muted' ? '#64748b'
                   : '#6b7280';

  return `
  <tr>
    <td style="padding:12px 0;border-top:1px solid #e5e7eb;vertical-align:top">
      <div style="font-weight:600;font-size:15px;margin-bottom:6px">
        ${i+1}. <a href="${url}" style="color:#0ea5e9;text-decoration:none">${t}</a>
      </div>
      <div style="color:#374151;font-size:14px;line-height:1.55">${sum}</div>
      <div style="margin-top:8px;font-size:12px;color:#6b7280">
        <span>Source: ${src}</span>
        ${pub ? `<span style="margin-left:8px">• Published: ${pub}</span>` : ``}
      </div>
      <div style="margin-top:8px;font-size:12px">
        <span style="display:inline-block;background:${senColor};color:#fff;padding:2px 8px;border-radius:999px;margin-right:6px">Sentiment: ${sen || 'Neutral'}</span>
        ${imp ? `<span style="display:inline-block;background:${impColor};color:#fff;padding:2px 8px;border-radius:999px;margin-right:6px">Impact: ${imp}</span>` : ``}
        ${rat ? `<span style="color:#6b7280">( ${rat} )</span>` : ``}
      </div>
      ${ticks ? `<div style="margin-top:6px;font-size:12px;color:#334155">Tickers: <strong>${ticks}</strong></div>` : ``}
    </td>
  </tr>`;
}).join('') || `
  <tr><td style="padding:12px 0;border-top:1px solid #e5e7eb;color:#6b7280">
    ไม่มีข่าวที่เข้าเกณฑ์หรือเกี่ยวข้องกับ watchlist ในรอบนี้
  </td></tr>
`;

const footer = `
  <div style="margin-top:16px;color:#94a3b8;font-size:12px;border-top:1px solid #e5e7eb;padding-top:8px">
    ส่งอัตโนมัติโดย n8n • เวลาระบบ: ${new Date().toLocaleString('th-TH',{ timeZone:'Asia/Bangkok' })}
  </div>
</div>`;

const html = `${header}<table style="width:100%;border-collapse:collapse">${rows}</table>${footer}`;

// SUBJECT แนะนำแนวนี้
const subject = `${title} — ${asOf}`;

return [{
  json: {
    subject,
    html,
    count: items.length
  }
}];

// สร้างหน้าต่างเวลาแจ้งเตือน 48 ชม.ข้างหน้า (ปรับได้)
// ใช้ Asia/Bangkok ให้สอดคล้องเวลาจริง
const now = new Date();
const end = new Date(now.getTime() + 48 * 60 * 60 * 1000); // +48h

return [{
  json: {
    timeMin: now.toISOString(),
    timeMax: end.toISOString()
  }
}];

// ---- ตั้งค่าคีย์เวิร์ดที่อยากจับคู่ (แก้ไข/เพิ่มได้) ----
const KEYWORDS = [
  // AGM / ผู้ถือหุ้น
  'ประชุมผู้ถือหุ้น', 'AGM', 'E-AGM',
  // งบการเงิน / ผลประกอบการ
  'งบการเงิน', 'งวดไตรมาส', 'ผลประกอบการ', 'ประกาศงบ', 'earnings',
  // ปันผล / XD / XM / XR
  'ปันผล', 'XD', 'XM', 'XR', 'dividend'
];

// จำกัดช่วงวันล่วงหน้า (หน่วยวัน) ที่ต้องการเตือน
const ALERT_WINDOW_DAYS = 14;

// ฟังก์ชันช่วย
const toDate = (s) => s ? new Date(s) : null;
const daysBetween = (a, b) => Math.ceil((a - b) / (1000 * 60 * 60 * 24));
const text = (v) => (v || '').toString();

// ดึงรายการอีเวนต์จาก input (Google Calendar – Get many events)
const items = $input.all();

// Google Calendar node ปกติจะส่งออกเป็นอาร์เรย์ของอีเวนต์ใน items[x].json
// รองรับทั้งกรณี “Return All” และใส่ “Limit”
let events = [];
for (const it of items) {
  const ev = it.json;
  // บาง credential/เวอร์ชันจะให้มาเป็นอาร์เรย์ในฟิลด์ 'data' หรือ 'events'
  if (Array.isArray(ev)) events.push(...ev);
  else if (Array.isArray(ev.data)) events.push(...ev.data);
  else if (Array.isArray(ev.events)) events.push(...ev.events);
  else events.push(ev);
}

// Normalize ฟิลด์ที่เราต้องการ
const now = new Date();
const normalized = events.map((ev) => {
  // โครงสร้างมาตรฐานของ Calendar API: ev.summary, ev.description, ev.start, ev.end, ev.htmlLink, ev.location
  const startStr = ev.start?.dateTime || ev.start?.date; // all-day event อาจเป็น date
  const endStr   = ev.end?.dateTime   || ev.end?.date;

  const start = toDate(startStr);
  const end   = toDate(endStr);

  // daysUntil: ใช้เริ่มต้นอีเวนต์
  const daysUntil = (start) ? daysBetween(start, now) : null;

  // รวมข้อความสำหรับค้นคีย์เวิร์ด
  const blob = [
    ev.summary, ev.description, ev.location
  ].map(text).join(' ').toLowerCase();

  const matchedKeywords = KEYWORDS.filter(k => blob.includes(k.toLowerCase()));

  // label ประเภทอีเวนต์แบบง่ายๆ จาก keyword
  let eventType = null;
  if (matchedKeywords.some(k => ['ปันผล','xd','xm','xr','dividend'].includes(k.toLowerCase()))) {
    eventType = 'Dividend';
  } else if (matchedKeywords.some(k => ['งบการเงิน','ผลประกอบการ','ประกาศงบ','earnings'].includes(k.toLowerCase()))) {
    eventType = 'Earnings';
  } else if (matchedKeywords.some(k => ['ประชุมผู้ถือหุ้น','agm','e-agm'].includes(k.toLowerCase()))) {
    eventType = 'AGM';
  }

  return {
    title: ev.summary || '(No title)',
    description: ev.description || '',
    start: startStr || '',
    end: endStr || '',
    location: ev.location || '',
    link: ev.htmlLink || ev.hangoutLink || '',
    daysUntil,
    matchedKeywords,
    eventType
  };
});

// กรองเฉพาะอีเวนต์ที่:
// 1) อยู่ในช่วงล่วงหน้าไม่เกิน ALERT_WINDOW_DAYS
// 2) มีคีย์เวิร์ดที่สนใจอย่างน้อย 1 คำ
const filtered = normalized.filter(e =>
  e.daysUntil !== null &&
  e.daysUntil >= 0 &&
  e.daysUntil <= ALERT_WINDOW_DAYS &&
  e.matchedKeywords.length > 0
);

// ส่งออก 1 item เพื่อให้ If ใช้ตรวจ count ได้ง่าย
return [{
  json: {
    count: filtered.length,
    windowDays: ALERT_WINDOW_DAYS,
    events: filtered
  }
}];
